def roman_value(text):
    table = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    for i, c in enumerate(text):
        v = table[c]
        if i + 1 < len(text) and v < table[text[i + 1]]:
            total -= v
        else:
            total += v
    return total
